L6=7
def transform(g, L6=L6):
    h,w=len(g),len(g[0])
    o=[row[:] for row in g]
    cells=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c] not in (0,)]
    def put(r,c,v):
        if 0<=r<h and 0<=c<w: o[r][c]=v
    for r,c,v in cells:
        if v==1:
            m=min(c+2,w-2)
            for cc in range(m-2,m+1): put(r,cc,5)
            put(r,m-2,1); put(r-1,m,1)
        elif v==2:
            for i,cc in enumerate(range(c-4,c+1)): put(r,cc,2 if i in(0,4) else 5)
        elif v==3:
            for i in range(4): put(r+i,c,3 if i in(0,3) else 5)
        elif v==6:
            for i in range(L6):
                rr=r-i
                if rr<0: break
                put(rr,c,6 if i in(0,L6-1) else 5)
    # intersections: cells painted 4 = on 2-bar and on vertical(3/6) line; then diagonal down-left
    # detect: for each pair, crossing of row of a 2-bar with col of a 3/6 line
    twos=[(r,c) for r in range(h) for c in range(w) if g[r][c]==2]
    verts=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c] in (3,6)]
    for r2,c2 in twos:
        for r3,c3,v3 in verts:
            # 2-bar spans row r2, cols c2-4..c2 ; vert line spans col c3, rows r3..r3+3 (3) or r3-L6+1..r3 (6)
            if c2-4<=c3<=c2:
                rows = range(r3,r3+4) if v3==3 else range(r3-L6+1,r3+1)
                if r2 in rows:
                    put(r2,c3,4)
                    rr,cc=r2,c3
                    while rr+1<h and cc-1>=0:
                        rr+=1; cc-=1; put(rr,cc,4)
    return o

